394	}
395	
396	impl ChangedFiles {
397	    /// The project's own files between `before` and `after` in the
398	    /// repository `top`, never what the application keeps in `.suspense` or
399	    /// its draft, each marked as the agent's where it is among `edited`; none
400	    /// where git can't say.
401	    fn read(top: PathBuf, before: String, after: String, edited: &[PathBuf]) -> Option<Self> {
402	        let changes =
403	            task_snapshot::project_own(task_snapshot::changes(&top, &before, &after).ok()?);
404	        let by_agent = |path: &Path| {
405	            let full = shell_paths::normalize(&top.join(path));
406	            edited.iter().any(|edited| *edited == full)
407	        };
408	        let files = changes
409	            .into_iter()
410	            .map(|change| {
411	                let agent = by_agent(&change.path)
412	                    || change.from.as_deref().is_some_and(|from| by_agent(from));
413	                (change, agent)
414	            })
415	            .collect();
416	        Some(Self {
417	            top,
418	            before,
419	            after,
420	            files,
421	        })
422	    }
423	}
