625	    /// A task from the history of the project `project_dir`, whose files are
626	    /// read from there, and, in a git repository, with the files that changed
627	    /// while it ran. Called off the UI thread, since that asks git.
628	    fn restore_in(saved: SavedPrompt, project_dir: Option<&Path>) -> Self {
629	        let snapshots = saved.record.as_ref().and_then(|record| {
630	            Some((
631	                record.snapshot_before.clone()?,
632	                record.snapshot_after.clone()?,
633	            ))
634	        });
635	        let mut task = Self::restore_replayed(saved, project_dir);
636	        if let (Some(dir), Some((before, after))) = (project_dir, snapshots)
637	            && let Some(top) = task_snapshot::repo_top(dir)
638	        {
