645	    fn restore_replayed(saved: SavedPrompt, project_dir: Option<&Path>) -> Self {
646	        let mut task = Self::new(saved.text.into());
647	        task.references = referenced_spec::References::new(project_dir.map(Path::to_path_buf));
648	        task.name = saved.anchor.name().to_string().into();
649	        task.mode = anchor_mode(&saved.anchor);
650	        task.sent = SentAs::of(&saved.anchor);
651	        task.new_conversation = saved.anchor.new_conversation.unwrap_or(false);
652	        task.model = saved.anchor.model.clone();
653	        task.effort = saved.anchor.effort.clone();
654	        task.added_steps = saved.anchor.added_steps.clone();
655	        task.asked_at = (saved.sent_at > 0).then_some(saved.sent_at);
656	        task.marked_done = saved
657	            .record
658	            .as_ref()
659	            .is_some_and(|record| record.marked_done);
660	        task.picked = saved
661	            .record
662	            .as_ref()
663	            .map(|record| record.picked.clone())
664	            .unwrap_or_default();
665	        task.sent_prompts = saved
666	            .record
667	            .as_ref()
668	            .map(|record| record.sent_prompts.clone())
669	            .unwrap_or_default();
670	        let recorded_at = saved.recorded_at;
671	        let Some(record) = saved.record.filter(|record| !record.holds_only_the_mark()) else {
672	            task.reply.stop();
673	            task.status = TaskStatus::Unrecorded;
674	            return task;
675	        };
676	        // Only a record holding both its start and its end says how long;
677	        // one recorded before they were kept, as well as can be told.
678	        if let (Some(started), Some(ended)) = (record.started_at, record.ended_at) {
679	            task.started = Some(from_millis(started));
680	            task.ended = Some(from_millis(ended));
681	        } else if let Some(recorded_at) = recorded_at.filter(|_| saved.sent_at > 0) {
682	            let sent = std::time::UNIX_EPOCH + Duration::from_secs(saved.sent_at);
683	            task.estimated = (recorded_at >= sent).then_some((sent, recorded_at));
684	        }
685	        task.given = record.harness().map(|harness| Given {
686	            harness,
687	            system_prompt: record.system_prompt.clone(),
688	            instructions: record.instructions.clone(),
689	            resumed: record.resumed,
690	        });
691	        if let Some(markdown) = record.user_prompt.clone() {
692	            task.set_compiled(Compiled::new(
693	                saved.anchor.name().to_string().into(),
694	                markdown,
695	            ));
696	        }
697	        for event in record.events() {
698	            task.apply(event);
699	        }
700	        if record.cancelled {
701	            task.cancel();
702	        } else if let Some(error) = record.error {
703	            task.apply(HarnessEvent::Failed(error));
704	        }
705	        task.end();
706	        task
707	    }
