717	    /// Folds a harness event into the task's output and status.
718	    fn apply(&mut self, event: HarnessEvent) {
719	        self.apply_event(event);
720	        self.settle_outcome();
721	        self.stamp_end();
722	    }
723	
724	    /// Once it is over, keeps when, so its running time stops there.
725	    fn stamp_end(&mut self) {
726	        if self.started.is_some() && !self.status.is_active() && self.ended.is_none() {
727	            self.ended = Some(std::time::SystemTime::now());
728	        }
729	    }
730	
731	    /// When it was sent and, once it is over, when it ended, and whether
732	    /// that is only as well as can be told; none when neither is known.
733	    fn span(&self) -> Option<(std::time::SystemTime, Option<std::time::SystemTime>, bool)> {
734	        match (self.started, self.estimated) {
735	            (Some(started), _) => Some((started, self.ended, false)),
736	            (None, Some((sent, recorded))) => Some((sent, Some(recorded), true)),
737	            (None, None) => None,
738	        }
739	    }
740	
741	    /// How long it has been under way, or took, and whether that is only
742	    /// approximate; none when it can't be told.
743	    fn took(&self) -> Option<Took> {
744	        let (started, ended, approximate) = self.span()?;
745	        let until = match ended {
746	            Some(ended) => ended,
747	            None if self.status.is_active() => std::time::SystemTime::now(),
748	            None => return None,
749	        };
750	        Some(Took {
751	            time: until.duration_since(started).unwrap_or_default(),
752	            approximate,
753	        })
754	    }
