756	    /// Once its run is over, heads its final summary with what it did: the
757	    /// spec, code, or other files its tool calls wrote or edited, and with
758	    /// none, whether it answered.
759	    fn settle_outcome(&mut self) {
760	        if !self.reply.done {
761	            return;
762	        }
763	        let project_dir = self.references.project_dir().to_path_buf();
764	        let root = |key: &str| {
765	            crate::hidden_anchor::config_value(&project_dir, key)
766	                .ok()
767	                .map(|dir| shell_paths::normalize(&project_dir.join(dir)))
768	        };
769	        let spec_dir = self.spec_dir.clone().or_else(|| root("root"));
770	        let code_dir = root("codeRoot");
771	        let tags = crate::task_table::outcome_tags(
772	            &self.references.edited_paths(),
773	            &project_dir,
774	            spec_dir.as_deref(),
775	            code_dir.as_deref(),
776	            self.reply.final_output().is_some(),
777	        );
778	        self.reply.set_outcome(tags);
779	    }
780	
781	    fn apply_event(&mut self, event: HarnessEvent) {
782	        if let HarnessEvent::Session(id) = &event {
783	            self.session.get_or_insert_with(|| id.clone().into());
784	        }
785	        // Its container's image builds before the harness runs.
786	        match &event {
787	            HarnessEvent::Preparing if self.status.is_active() => {
788	                self.status = TaskStatus::Preparing
789	            }
790	            HarnessEvent::Prepared if self.status == TaskStatus::Preparing => {
791	                self.status = TaskStatus::Running
792	            }
793	            _ => {}
794	        }
795	        self.references.apply(&event);
796	        self.subagents.apply(&event);
797	        match self.reply.apply(event) {
798	            Some(error) => self.fail(error),
799	            None if self.reply.done && self.status == TaskStatus::Running => {
800	                self.status = TaskStatus::Done
801	            }
802	            None => {}
803	        }
804	    }
805	
806	    fn fail(&mut self, error: String) {
807	        self.reply.push_error(error);
808	        // A task cancelled stays cancelled, whatever its harness says after.
809	        if self.status != TaskStatus::Cancelled {
810	            self.status = TaskStatus::Failed;
811	        }
812	        self.stamp_end();
813	    }
814	
815	    /// Cancels it, keeping the output it had so far: tool calls still running
816	    /// were cancelled with it.
817	    fn cancel(&mut self) {
818	        self.status = TaskStatus::Cancelled;
819	        self.subagents.end();
820	        self.reply.cancel();
821	        self.stamp_end();
822	    }
823	
824	    /// Whether it can be cancelled: it is under way, sent from here.
825	    fn can_cancel(&self) -> bool {
826	        self.status.is_active() && self.cancel.is_some()
827	    }
828	
829	    /// The run is over. One that ended without a result, as when the harness
830	    /// was stopped, failed, and nothing still running in it finished.
831	    fn end(&mut self) {
832	        self.end_run();
833	        self.settle_outcome();
834	        self.stamp_end();
835	    }
836	
837	    fn end_run(&mut self) {
838	        self.subagents.end();
839	        // Cancelled, what it printed before it stopped is kept, and any call
840	        // in it still running was cancelled with it.
841	        if self.status == TaskStatus::Cancelled {
842	            self.reply.cancel();
843	            return;
844	        }
845	        if self.reply.done {
846	            return;
847	        }
848	        self.reply.stop();
849	        if self.status != TaskStatus::Failed {
850	            self.fail("The harness stopped without a result.".into());
851	        }
852	    }
853	}
