    fn finished(
        session: &mut Option<Self>,
        id: String,
        context: Option<u64>,
        project_dir: &Path,
        sent: Option<&str>,
    ) {
        if session.as_ref().is_some_and(|session| session.id == id) {
            return;
        }
        *session = Some(Self {
            project_dir: project_dir.to_path_buf(),
            in_container: None,
            id,
            context,
            system_prompt: sent.map(str::to_string),
