/// What a run is told to keep off: `root`, where it may not edit, and
/// `unread`, where it may not read, which Claude Code is told so the
/// harness knows at once. That is only a nudge: a shell command can still
/// reach them, and nothing is put back or stops the run when one does.
///
/// A run in a container, as `container` says, is kept off nothing this way:
/// it sees only what is mounted into it.
#[derive(Clone, Debug, Default)]
pub struct Protected {
    pub root: Option<PathBuf>,
    pub unread: Option<PathBuf>,
    /// The container the run goes in, if it runs in one rather than on the
    /// host.
    pub container: Option<container::Plan>,
    /// The model the run goes to, as the harness is told it; none for its
    /// own. Not kept off anything: only how the run is set up.
    pub model: Option<String>,
    /// The reasoning effort the run goes with, as the harness is told it,
    /// Codex's only; none for its own. Not kept off anything: only how the
    /// run is set up.
    pub effort: Option<String>,
    /// The other files attached to the run's prompt, on the host, which
    /// must be there before it runs. Not kept off anything.
    pub files: Vec<PathBuf>,
    /// Where the run's conversation's session is copied once it is over:
    /// the `.session` folder beside its history record.
    pub session_copy: Option<PathBuf>,
}

