/// `template` with each `<name>` in `values` replaced with its value.
pub fn fill(template: &str, values: &[(&str, &str)]) -> String {
    values
        .iter()
        .fold(template.to_string(), |text, (name, value)| {
            text.replace(&format!("<{name}>"), value)
        })
}

